input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3id.org/bricks/context#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?meter ?ts ?name WHERE {
  ?meter a brick:Electric_Power_Sensor ;
          brick:hasProperty brick:Electric_Power ;
          brick:hasLocation ?bldg .
  OPTIONAL { ?bldg rdfs:label ?name . }
  ?meter ref:hasExternalReference ?ts .
  ?mref a ref:TimeseriesReference ; ref:hasTimeseriesId ?tsId ; ref:references ?meter .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?m ?loc ?pointOf WHERE {
  ?m a brick:Electric_Power_Sensor .
  OPTIONAL { ?m brick:hasLocation ?loc . }
  OPTIONAL { ?m brick:isPointOf ?pointOf . }
} LIMIT 40

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?meter ?ts WHERE {
  ?meter a brick:Building_Electrical_Meter .
  OPTIONAL { ?meter ref:hasExternalReference ?tsref . ?tsref ref:hasTimeseriesId ?ts . }
}
